class BaseLayer:
    def __init__(self, dim):
        self.dim = dim
    def forward(self, x):
        return x + self.dim

class ResidualLayer(BaseLayer):
    def __init__(self, dim, scale=2):
        super().__init__(dim)
        self.scale = scale
    def forward(self, x):
        base_out = super().forward(x)
        return base_out * self.scale

layer = ResidualLayer(3, scale=4)
print(layer.forward(7))

